  ret = ssd1306_sendbyte(priv, SSD1306_CMNPAD_CONFIG);
  if (ret < 0)
    {
      return ret;
    }

  /* 0x12 or 0x02 */

  ret = ssd1306_sendbyte(priv, SSD1306_CMNPAD(SSD1306_DEV_CMNPAD));
  if (ret < 0)
    {
      return ret;
    }

