 119	static uint32_t voice_elapsed_ms(FAR const struct timespec *start,
 120	                                 FAR const struct timespec *end)
 121	{
 122	  int64_t elapsed_ns;
 123	
 124	  elapsed_ns = ((int64_t)end->tv_sec - (int64_t)start->tv_sec) *
 125	               NSEC_PER_SEC;
 126	  elapsed_ns += (int64_t)end->tv_nsec - (int64_t)start->tv_nsec;
 127	  return elapsed_ns > 0 ? (uint32_t)(elapsed_ns / NSEC_PER_MSEC) : 0;
