 363	static int voice_oled_show(struct voice_oled_s *oled, const char *line1,
 364	                           const char *line2)
 365	{
 366	  const char *lines[2] = {line1, line2};
 367	  uint8_t row[128 / 8];
 368	  unsigned int y;
 369	  int ret = 0;
 370	
 371	  if (!oled->available)
 372	    {
 373	      return 0;
 374	    }
 375	
 376	  for (y = 0; y < 64; y++)
 377	    {
 378	      const char *text;
 379	      unsigned int x;
 380	      unsigned int charrow;
 381	
 382	      memset(row, 0, sizeof(row));
 383	      text = lines[y / 32];
 384	      charrow = (y % 32) / 3;
 385	
 386	      if (charrow < 7)
 387	        {
 388	          for (x = 0; text[x] != '\0' && x < 20; x++)
 389	            {
 390	              uint8_t glyph = (uint8_t)text[x];
 391	              unsigned int col;
 392	
 393	              if (glyph >= sizeof(g_font) || glyph < ' ')
 394	                {
 395	                  glyph = ' ';
 396	                }
 397	
 398	              for (col = 0; col < 5; col++)
 399	                {
 400	                  if ((g_font[glyph][col] & (1u << charrow)) != 0)
 401	                    {
 402	                      voice_oled_pixel(row, x * 6 + col, true);
 403	                    }
 404	                }
 405	            }
 406	        }
 407	
 408	      ret = oled->plane.putrun(oled->dev, y, 0, row, 128);
 409	      if (ret < 0)
 410	        {
 411	          oled->available = false;
 412	          printf("OLED unavailable\n");
 413	          return ret;
 414	        }
 415	    }
 416	
 417	  return 0;
 418	}
