306	void agent_oled_enqueue(const char *content)
307	{
308	  struct agent_oled_slot_s *slot;
309	  size_t len;
310	
311	  if (content == NULL || !g_oled_started || g_oled_disabled)
312	    return;
313	
314	  len = strnlen(content, AGENT_OLED_TEXT_CAPACITY - 1);
315	  pthread_mutex_lock(&g_oled_queue.lock);
316	
317	  if (g_oled_disabled)
318	    {
319	      pthread_mutex_unlock(&g_oled_queue.lock);
320	      return;
321	    }
322	
323	  if (g_oled_queue.count == AGENT_OLED_QUEUE_DEPTH)
324	    {
325	      g_oled_queue.head = (g_oled_queue.head + 1) % AGENT_OLED_QUEUE_DEPTH;
326	      g_oled_queue.count--;
327	    }
328	
329	  slot = &g_oled_queue.slots[g_oled_queue.tail];
330	  memcpy(slot->text, content, len);
331	  slot->text[len] = '\0';
332	  slot->len = len;
333	  g_oled_queue.tail = (g_oled_queue.tail + 1) % AGENT_OLED_QUEUE_DEPTH;
334	  g_oled_queue.count++;
335	  pthread_cond_signal(&g_oled_queue.available);
336	  pthread_mutex_unlock(&g_oled_queue.lock);
337	
338	  syslog(LOG_INFO, "[OLED-DIAG] enqueue len=%zu\n", len);
339	}
