   115	static void net_state_change_cb(net_state_t state, void* arg)
   116	{
   117	    (void)arg;
   118	    if (state == NET_STATE_CONNECTED && !g_net_services_started) {
   119	        syslog(LOG_INFO, "[%s] Network recovered, starting services\n", TAG);
   120	#ifdef CONFIG_AI_AGENT_FEISHU
   121	        feishu_bot_start();
   122	#endif
   123	        agent_loop_start();
   124	        ws_server_start();
   125	#ifdef CONFIG_AI_AGENT_NODE
