   129	        mqtt_channel_start();
   130	#endif
   131	#ifdef CONFIG_AI_AGENT_WEIXIN
   132	        weixin_channel_start();
   133	#endif
   134	        g_net_services_started = true;
   135	    } else if (state == NET_STATE_DISCONNECTED) {
   136	        syslog(LOG_WARNING,
   137	            "[%s] Network lost, services may be affected\n", TAG);
   138	        /* Services will handle disconnection via their own error paths.
   139	         * We just log the event here. g_net_services_started stays true
   140	         * so we don't re-start services that are already running. */
   141	    }
   142	}
