   145	/**
   146	 * Runs in a background thread: waits for network, then starts all
   147	 * network-dependent services. Main thread is NOT blocked.
   148	 */
   149	static void* network_watch_task(void* arg)
   150	{
   151	    (void)arg;
   152	    syslog(LOG_INFO, "[%s] Network watcher started\n", TAG);
   153	
   154	    network_wifi_reconnect();
   155	
   156	    if (network_wait_connected(30000) == OK) {
   157	        syslog(LOG_INFO, "[%s] Network connected: %s\n", TAG, network_get_ip());
   158	
   159	#if AGENT_SKILL_SYNC_ENABLED
   160	        /* Sync skills from Bitable before starting agent loop */
   161	        if (skill_sync_from_bitable() != OK) {
   162	            syslog(LOG_WARNING, "[%s] Bitable skill sync failed, using local skills\n", TAG);
   163	        }
   164	#endif
   165	
   166	#ifdef CONFIG_AI_AGENT_FEISHU
   167	        if (feishu_bot_start() != OK)
   168	            syslog(LOG_WARNING, "[%s] feishu_bot_start failed\n", TAG);
   169	#endif
   170	        if (agent_loop_start() != OK)
   171	            syslog(LOG_WARNING, "[%s] agent_loop_start failed\n", TAG);
   172	        if (ws_server_start() != OK)
   173	            syslog(LOG_WARNING, "[%s] ws_server_start failed\n", TAG);
   174	#ifdef CONFIG_AI_AGENT_NODE
   175	        if (node_client_start() != OK)
   176	            syslog(LOG_WARNING, "[%s] node_client_start failed\n", TAG);
   177	#endif
   178	#ifdef CONFIG_AI_AGENT_MQTT
   179	        if (mqtt_channel_start() != OK)
   180	            syslog(LOG_WARNING, "[%s] mqtt_channel_start failed\n", TAG);
   181	#endif
   182	#ifdef CONFIG_AI_AGENT_WEIXIN
   183	        if (weixin_channel_start() != OK)
   184	            syslog(LOG_WARNING, "[%s] weixin_channel_start failed\n", TAG);
   185	#endif
   186	
   187	        syslog(LOG_INFO, "[%s] All network services started!\n", TAG);
   188	
   189	#ifdef CONFIG_AI_AGENT_NET_RPMSG
   190	        g_net_services_started = true;
   191	#endif
   192	    } else {
   193	        syslog(LOG_WARNING, "[%s] Network timeout — net services not started.\n", TAG);
   194	        syslog(LOG_WARNING, "[%s] Use 'config_show' / 'set_*' CLI commands to configure.\n", TAG);
   195	    }
   196	
   197	#ifdef CONFIG_AI_AGENT_NET_RPMSG
   198	    /* Register listener for network state changes — auto-restart services on reconnect */
   199	    network_register_listener(net_state_change_cb, NULL);
   200	
   201	    /* Keep thread alive to handle reconnection events */
   202	    while (!g_shutdown_requested) {
   203	        sleep(1);
   204	    }
   205	#endif
   206	
   207	    return NULL;
   208	}
