   233	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
   234	    };
   235	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_IN, O_RDONLY | O_CREAT, 0666, &attr);
   236	    if (mq == (mqd_t)-1) {
   237	        syslog(LOG_ERR, "[%s] Failed to open quickapp inbound mqueue: %d\n", TAG, errno);
