   241	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
   242	    if (!buf) {
   243	        syslog(LOG_ERR, "[%s] Failed to allocate mqueue recv buffer\n", TAG);
   244	        mq_close(mq);
   245	        return NULL;
   246	    }
   247	
   248	    while (1) {
   249	        ssize_t n = mq_receive(mq, buf, VELACLAW_MQ_MSG_SIZE, NULL);
   250	        if (n < 0) {
   280	    }
   281	
   282	    free(buf);
   283	    mq_close(mq);
   284	    return NULL;
   285	}
