   287	/**
   288	 * Send a reply to the quickapp process via the outbound mqueue.
   289	 * Called from the outbound dispatch thread in the agent process.
   290	 */
   291	static void quickapp_mq_dispatch(const char *chat_id, const char *content)
   292	{
   293	    struct mq_attr attr = {
   294	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
   295	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
   296	    };
   297	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_OUT, O_WRONLY | O_CREAT, 0666, &attr);
   298	    if (mq == (mqd_t)-1) {
   299	        syslog(LOG_ERR, "[%s] quickapp dispatch: mq_open failed: %d\n", TAG, errno);
   300	        return;
   301	    }
   302	
   303	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
   304	    if (!buf) {
   305	        mq_close(mq);
   306	        return;
   307	    }
   308	    int len = snprintf(buf, VELACLAW_MQ_MSG_SIZE, "%s\n%s", chat_id, content);
   309	    if (len >= (int)VELACLAW_MQ_MSG_SIZE) {
   310	        len = VELACLAW_MQ_MSG_SIZE - 1;
   311	        buf[len] = '\0';
   312	    }
   313	
   314	    if (mq_send(mq, buf, len + 1, 0) != 0) {
   315	        syslog(LOG_ERR, "[%s] quickapp dispatch: mq_send failed: %d\n", TAG, errno);
   316	    } else {
   317	        syslog(LOG_INFO, "[%s] quickapp dispatch: reply sent chat_id=%s\n", TAG, chat_id);
   318	    }
   319	    free(buf);
   320	    mq_close(mq);
   321	}
