   436	            fflush(stdout);
   437	            pthread_mutex_unlock(&g_stdout_lock);
   438	            syslog(LOG_INFO, "[agent] [Agent]: %s\n", msg.content);
   439	        } else {
   440	            syslog(LOG_WARNING, "[%s] Unknown channel: %s\n", TAG, msg.channel);
   441	        }
   442	
   443	        free(msg.content);
   444	    }
   445	
   446	    syslog(LOG_INFO, "[%s] Outbound dispatch exiting\n", TAG);
   447	    return NULL;
   448	}
