#include "llm/llm_cache.h"

#include "infra/config_store.h"
#include "llm/llm_internal.h"

#include <inttypes.h>
#include <stdbool.h>
#include <pthread.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <time.h>

static const char* TAG = "llm_cache";

typedef struct {
    uint32_t hash;
    char* response;
    uint64_t ts_ms; /* monotonic milliseconds when stored */
    uint32_t hits;
    int tokens; /* total_tokens when cached */
} llm_cache_slot_t;

static llm_cache_slot_t s_slots[LLM_CACHE_SLOTS];
static pthread_mutex_t s_cache_lock = PTHREAD_MUTEX_INITIALIZER;
static uint32_t s_tokens_saved;
static uint32_t s_total_hits;
static uint32_t s_context_hash;
static bool s_context_valid;

/* djb2 hash over first LLM_CACHE_KEY_LEN chars */

static uint32_t djb2_hash(const char* str, size_t len)
{
    uint32_t h = 5381;
    size_t n = len < LLM_CACHE_KEY_LEN ? len : LLM_CACHE_KEY_LEN;

    for (size_t i = 0; i < n; i++) {
        h = ((h << 5) + h) + (unsigned char)str[i];
    }
    return h;
}

static uint32_t context_hash(void)
{
    char model[64] = { 0 };
    char api_key[128] = { 0 };
    char host[128] = { 0 };
    char path[128] = { 0 };
    char port[8] = { 0 };
    uint32_t h = 2166136261u;

    llm_snapshot_config(model, sizeof(model), api_key, sizeof(api_key),
        host, sizeof(host));
    claw_config_get(AGENT_CFG_KEY_LLM_PATH, path, sizeof(path));
    claw_config_get("llm_port", port, sizeof(port));

#define HASH_CONTEXT_FIELD(field) \
    do { \
        const char *p = (field); \
        while (*p) { \
            h ^= (unsigned char)*p++; \
            h *= 16777619u; \
        } \
        h ^= 0xffu; \
        h *= 16777619u; \
    } while (0)

    HASH_CONTEXT_FIELD(model);
    HASH_CONTEXT_FIELD(api_key);
    HASH_CONTEXT_FIELD(host);
    HASH_CONTEXT_FIELD(path);
    HASH_CONTEXT_FIELD(port);
#undef HASH_CONTEXT_FIELD

    return h;
}

static bool monotonic_ms(uint64_t *out)
{
    struct timespec ts;

    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return false;
    }

    *out = (uint64_t)ts.tv_sec * 1000ULL
        + (uint64_t)ts.tv_nsec / 1000000ULL;
    return true;
}

static void clear_locked(void)
{
    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
        free(s_slots[i].response);
        memset(&s_slots[i], 0, sizeof(s_slots[i]));
    }
    s_tokens_saved = 0;
    s_total_hits = 0;
}

/* Configuration changes isolate all old answers, including old failures. */
static void sync_context(void)
{
    uint32_t current = context_hash();

    pthread_mutex_lock(&s_cache_lock);
    if (!s_context_valid || s_context_hash != current) {
        clear_locked();
        s_context_hash = current;
        s_context_valid = true;
    }
    pthread_mutex_unlock(&s_cache_lock);
}

void llm_cache_init(void)
{
    pthread_mutex_lock(&s_cache_lock);
    clear_locked();
    s_context_hash = context_hash();
    s_context_valid = true;
    pthread_mutex_unlock(&s_cache_lock);
    syslog(LOG_INFO, "[%s] Cache initialized (%d slots, TTL %ds)\n",
        TAG, LLM_CACHE_SLOTS, LLM_CACHE_TTL_SEC);
}

char* llm_cache_get(const char* prompt, size_t prompt_len)
{
    if (!prompt || prompt_len == 0) {
        return NULL;
    }

    uint32_t h = djb2_hash(prompt, prompt_len);
    uint64_t now;
    char* result = NULL;

    if (!monotonic_ms(&now)) {
        return NULL;
    }
    sync_context();

    pthread_mutex_lock(&s_cache_lock);
    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
        llm_cache_slot_t* s = &s_slots[i];
        if (s->hash == h && s->response) {
            /* Check TTL */
            if (now < s->ts_ms ||
                now - s->ts_ms > (uint64_t)LLM_CACHE_TTL_SEC * 1000ULL) {
                free(s->response);
                memset(s, 0, sizeof(*s));
                break;
            }
            result = strdup(s->response);
            if (result) {
                s->hits++;
                s_total_hits++;
                if (s->tokens > 0) {
                    s_tokens_saved += (uint32_t)s->tokens;
                }
            }
            break;
        }
    }
    pthread_mutex_unlock(&s_cache_lock);
    return result;
}

void llm_cache_put(const char* prompt, size_t prompt_len,
    const char* response)
{
    if (!prompt || prompt_len == 0 || !response) {
        return;
    }

    uint32_t h = djb2_hash(prompt, prompt_len);
    uint64_t now;

    if (!monotonic_ms(&now)) {
        return;
    }
    sync_context();

    pthread_mutex_lock(&s_cache_lock);

    /* Find: existing slot with same hash, or LRU (oldest ts) */
    int target = 0;
    uint64_t oldest_ts = UINT64_MAX;

    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
        if (s_slots[i].hash == h) {
            target = i;
            break;
        }
        if (s_slots[i].ts_ms < oldest_ts) {
            oldest_ts = s_slots[i].ts_ms;
            target = i;
        }
    }

    llm_cache_slot_t* s = &s_slots[target];
    if (s->response) {
        free(s->response);
        s->response = NULL;
    }

    s->response = strdup(response);
    if (!s->response) {
        pthread_mutex_unlock(&s_cache_lock);
        return;
    }
    s->hash = h;
    s->ts_ms = now;
    s->hits = 0;

    pthread_mutex_unlock(&s_cache_lock);
}

void llm_cache_put_tokens(const char* prompt, size_t prompt_len,
    int total_tokens)
{
    if (!prompt || prompt_len == 0 || total_tokens <= 0) {
        return;
    }

    uint32_t h = djb2_hash(prompt, prompt_len);

    sync_context();

    pthread_mutex_lock(&s_cache_lock);
    for (int i = 0; i < LLM_CACHE_SLOTS; i++) {
        if (s_slots[i].hash == h && s_slots[i].response) {
            s_slots[i].tokens = total_tokens;
            break;
        }
    }
    pthread_mutex_unlock(&s_cache_lock);
}

uint32_t llm_cache_tokens_saved(void)
{
    uint32_t val;
    pthread_mutex_lock(&s_cache_lock);
    val = s_tokens_saved;
    pthread_mutex_unlock(&s_cache_lock);
    return val;
}

uint32_t llm_cache_hit_count(void)
{
    uint32_t val;
    pthread_mutex_lock(&s_cache_lock);
    val = s_total_hits;
    pthread_mutex_unlock(&s_cache_lock);
    return val;
}

void llm_cache_cleanup(void)
{
    pthread_mutex_lock(&s_cache_lock);
    clear_locked();
    s_context_valid = false;
    pthread_mutex_unlock(&s_cache_lock);
}

