677	cJSON* build_openai_tools_array(const char* tools_json)
678	{
679	    if (!tools_json) {
680	        return NULL;
681	    }
682	
683	    cJSON* tools_spec = cJSON_Parse(tools_json);
684	
685	    if (!tools_spec || !cJSON_IsArray(tools_spec)) {
686	        cJSON_Delete(tools_spec);
687	        return NULL;
688	    }
689	
690	    if (!agent_heap_gate_tools_parsed()) {
691	        return NULL;
692	    }
693	
694	    syslog(LOG_INFO,
695	        "[ALLOC-DIAG] tools_array before heap=%p size=%zu ra=%p\\n",
696	        (void *)USR_HEAP, sizeof(cJSON), __builtin_return_address(0));
697	
698	    cJSON* tools_arr = cJSON_CreateArray();
699	    cJSON* tool_def;
700	
701	    cJSON_ArrayForEach(tool_def, tools_spec)
702	    {
703	        cJSON* wrapper = cJSON_CreateObject();
704	
705	        cJSON_AddStringToObject(wrapper, "type", "function");
706	
707	        cJSON* func = cJSON_CreateObject();
708	        cJSON* name = cJSON_GetObjectItem(tool_def, "name");
709	        cJSON* desc = cJSON_GetObjectItem(tool_def, "description");
710	        cJSON* schema = cJSON_GetObjectItem(tool_def, "input_schema");
711	
712	        if (name && cJSON_IsString(name)) {
713	            cJSON_AddStringToObject(func, "name", name->valuestring);
714	        }
715	        if (desc && cJSON_IsString(desc)) {
716	            cJSON_AddStringToObject(func, "description",
717	                desc->valuestring);
718	        }
719	        if (schema) {
720	            cJSON_AddItemToObject(func, "parameters",
721	                cJSON_Duplicate(schema, 1));
722	        } else {
723	            cJSON* empty = cJSON_CreateObject();
724	            cJSON_AddStringToObject(empty, "type", "object");
725	            cJSON_AddItemToObject(empty, "properties",
726	                cJSON_CreateObject());
727	            cJSON_AddItemToObject(func, "parameters", empty);
728	        }
729	
730	        cJSON_AddItemToObject(wrapper, "function", func);
731	        cJSON_AddItemToArray(tools_arr, wrapper);
732	    }
733	
734	    cJSON_Delete(tools_spec);
735	    return tools_arr;
736	}
