428	static bool agent_heap_gate_count_membership(const struct mm_heap_s *heap,
429	    uintptr_t target, size_t max_steps, size_t *matches,
430	    struct agent_heap_gate_result_s *result)
431	{
432	    const struct mm_freenode_s *previous = &heap->mm_nodelist[0];
433	    const struct mm_freenode_s *current = previous->flink;
434	    size_t steps = 0;
435	
436	    *matches = 0;
437	    while (current != NULL) {
438	        bool is_free;
439	        int region;
440	        size_t size = 0;
441	
442	        if (steps >= max_steps) {
443	            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_CYCLE,
444	                -1, current, 0);
445	            return false;
446	        }
447	        steps++;
448	
449	        if (agent_heap_gate_sentinel_index(heap, current) < 0 &&
450	            (!agent_heap_gate_find_physical_node(heap, (uintptr_t)current,
451	                &is_free, &region, &size) || !is_free)) {
452	            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_NODE,
453	                -1, current, 0);
454	            return false;
455	        }
456	
457	        if ((uintptr_t)current == target) {
458	            if (!agent_heap_gate_add_count(matches)) {
459	                agent_heap_gate_fail(result,
460	                    AGENT_HEAP_GATE_FREELIST_MEMBERSHIP, -1, current, size);
461	                return false;
462	            }
463	        }
464	
465	        if ((uintptr_t)current->blink != (uintptr_t)previous) {
466	            agent_heap_gate_capture_links(result, current);
467	            agent_heap_gate_fail(result, AGENT_HEAP_GATE_LINK, -1,
468	                current, 0);
469	            return false;
470	        }
471	        if (!agent_heap_gate_is_valid_link(heap, current->flink)) {
472	            agent_heap_gate_capture_links(result, current);
473	            agent_heap_gate_fail(result, AGENT_HEAP_GATE_FREELIST_NODE, -1,
474	                current, 0);
475	            return false;
476	        }
477	
478	        previous = current;
479	        current = current->flink;
480	    }
481	
482	    return true;
483	}
