   225	static int alsa_read_frames(audio_capture_t* cap, void* buf,
   226	    snd_pcm_uframes_t frames)
   227	{
   228	    snd_pcm_uframes_t done = 0;
   229	    unsigned char* dst = buf;
   230	
   231	    while (done < frames) {
   232	        snd_pcm_sframes_t ret = snd_vela_pcm_readi(cap->handle.pcm,
   233	            dst + done * cap->hw_frame_bytes, frames - done);
   234	
   235	        if (ret == -EAGAIN) {
   236	            usleep(10 * 1000);
   237	            continue;
   238	        }
   239	
   240	        if (ret == -EPIPE) {
   241	            syslog(LOG_WARNING, "[%s] ALSA overrun, preparing capture\n",
   242	                TAG);
   243	            snd_vela_pcm_prepare(cap->handle.pcm);
   244	            continue;
   245	        }
   246	
   247	        if (ret == -ESTRPIPE) {
   248	            continue;
   249	        }
   250	
   251	        if (ret < 0) {
   252	            return done > 0 ? (int)done : (int)ret;
   253	        }
   254	
   255	        done += (snd_pcm_uframes_t)ret;
   256	    }
   257	
   258	    return (int)done;
   259	}
