   146	static void preproc_chunk(audio_preproc_t* pp,
   147	    unsigned char* buf, int bytes)
   148	{
   149	    if (!pp || (!pp->ns && !pp->agc)) {
   150	        return;
   151	    }
   152	
   153	    int16_t* samples = (int16_t*)buf;
   154	    int total = bytes / 2;
   155	    int fsz = PREPROC_FRAME_SIZE;
   156	    int32_t in32[PREPROC_FRAME_SIZE];
   157	    int32_t ref32[PREPROC_FRAME_SIZE];
   158	    int32_t out32[PREPROC_FRAME_SIZE];
   159	
   160	    memset(ref32, 0, sizeof(ref32));
   161	
   162	    for (int off = 0; off < total; off += fsz) {
   163	        int n = (off + fsz <= total) ? fsz : (total - off);
   164	
   165	        for (int i = 0; i < n; i++) {
   166	            in32[i] = samples[off + i];
   167	        }
   168	
   169	        if (pp->ns) {
   170	            ec2float_process(pp->ns, in32, ref32, n, out32);
   171	        } else {
   172	            memcpy(out32, in32, n * sizeof(int32_t));
   173	        }
   174	
   175	        if (pp->agc) {
   176	            for (int i = 0; i < n; i++) {
   177	                out32[i] <<= 8;
   178	            }
   179	            compexp_process_int24(pp->agc, out32, n);
   180	            for (int i = 0; i < n; i++) {
   181	                out32[i] >>= 8;
   182	            }
   183	        }
   184	
   185	        for (int i = 0; i < n; i++) {
   186	            int32_t v = out32[i];
   187	            if (v > 32767) {
   188	                v = 32767;
   189	            } else if (v < -32768) {
   190	                v = -32768;
   191	            }
   192	            samples[off + i] = (int16_t)v;
   193	        }
   194	    }
   195	}
