   272	    const unsigned char* data, size_t len)
   273	{
   274	    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
   275	
   276	    if (fd < 0) {
   277	        syslog(LOG_ERR, "[%s] Cannot create %s: %d\n",
   278	            TAG, path, errno);
   279	        return -errno;
   280	    }
   281	
   282	    ssize_t nw = write(fd, data, len);
   283	
   284	    close(fd);
   285	    return (nw == (ssize_t)len) ? 0 : -EIO;
