421	/* Direct path via vela_tls */
422	static int llm_http_direct(const char* post_data, resp_buf_t* rb,
423	    int* out_status)
424	{
425	    /* Snapshot config under lock */
426	    char api_key[128], llm_host[128], llm_path[128], llm_port[8], model[64];
427	    pthread_mutex_lock(&s_llm_lock);
428	    memcpy(api_key, s_api_key, sizeof(api_key));
429	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
430	    memcpy(llm_path, s_llm_path, sizeof(llm_path));
431	    memcpy(llm_port, s_llm_port, sizeof(llm_port));
432	    memcpy(model, s_model, sizeof(model));
433	    pthread_mutex_unlock(&s_llm_lock);
434	
435	    /* Allocate the response buffer once and hand it directly to the
436	     * TLS layer.  Previously we allocated a separate raw_buf and then
437	     * copied into resp_buf — doubling peak memory usage.  Now the
438	     * resp_buf IS the raw buffer, eliminating the copy. */
439	    size_t raw_cap = AGENT_LLM_STREAM_BUF_SIZE;
440	    if (resp_buf_init(rb, raw_cap) != OK)
441	        return ERROR;
442	
443	    /* OpenAI-compatible format: Authorization: Bearer <key> */
444	    char auth_header[256];
445	    snprintf(auth_header, sizeof(auth_header), "Bearer %s", api_key);
446	
447	    /* Extract provider ID from model string (e.g. "xiaomi/mimo-claw-0301" →
448	     * "xiaomi") Mify gateway requires X-Model-Provider-Id header for routing. */
449	    char provider[64] = { 0 };
450	    const char* slash = strchr(model, '/');
451	    if (slash) {
452	        size_t plen = (size_t)(slash - model);
453	        if (plen >= sizeof(provider))
454	            plen = sizeof(provider) - 1;
455	        memcpy(provider, model, plen);
456	    }
457	
458	    vela_header_t hdrs[] = { { "Authorization", auth_header },
459	        { provider[0] ? "X-Model-Provider-Id" : NULL,
460	            provider[0] ? provider : NULL },
461	        { NULL, NULL } };
462	
463	    int status;
464	    int use_tls = (strcmp(llm_port, "443") == 0);
465	
466	    if (use_tls) {
467	        status = vela_https_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
468	            rb->data, raw_cap);
469	    } else {
470	        status = vela_http_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
471	            rb->data, raw_cap);
472	    }
473	
474	    if (status < 0) {
475	        resp_buf_free(rb);
476	        return ERROR;
477	    }
478	
479	    /* Update length — TLS layer NUL-terminated the buffer */
480	    rb->len = strlen(rb->data);
481	
482	    *out_status = status;
483	    return OK;
484	}
