587	    pthread_mutex_lock(&s_llm_lock);
588	    use_tls = (strcmp(s_llm_port, "443") == 0);
589	    pthread_mutex_unlock(&s_llm_lock);
590	
591	#ifdef CONFIG_AI_AGENT_NET_RPMSG
592	    int retry_max = network_get_retry_max();
593	    int retry_base = network_get_retry_base_sec();
594	    int ret = ERROR;
595	
596	    for (int attempt = 0; attempt <= retry_max; attempt++) {
597	        if (attempt > 0) {
598	            /* Check network state before retrying */
599	            if (network_get_state() != NET_STATE_CONNECTED) {
600	                syslog(LOG_WARNING, "[llm] Network down, skip retry %d\n", attempt);
601	                break;
602	            }
603	            int delay = retry_base * (1 << (attempt - 1));
604	            syslog(LOG_INFO, "[llm] Retry %d/%d after %ds\n", attempt, retry_max, delay);
605	            sleep(delay);
606	        }
607	
608	        if (use_tls && http_proxy_is_enabled()) {
609	            ret = llm_http_via_proxy(post_data, rb, out_status);
610	        } else {
611	            ret = llm_http_direct(post_data, rb, out_status);
612	        }
613	
614	        if (ret == OK) {
615	            return OK;
616	        }
617	
618	        syslog(LOG_WARNING, "[llm] HTTP call failed (attempt %d/%d)\n",
619	            attempt + 1, retry_max + 1);
620	    }
621	
622	    /* All retries failed — notify user */
623	    syslog(LOG_ERR, "[llm] All %d retries failed\n", retry_max + 1);
624	    {
625	        agent_msg_t notify;
626	        memset(&notify, 0, sizeof(notify));
627	        strncpy(notify.channel, "cli", sizeof(notify.channel) - 1);
628	        notify.content = strdup("网络请求失败，请检查蓝牙连接");
629	        if (notify.content) {
630	            if (message_bus_push_outbound(&notify) != OK) {
631	                free(notify.content);
632	            }
633	        }
634	    }
635	    return ERROR;
636	#else
637	    if (use_tls && http_proxy_is_enabled())
638	        return llm_http_via_proxy(post_data, rb, out_status);
639	    return llm_http_direct(post_data, rb, out_status);
640	#endif
641	}
