790	int llm_chat_tools(const char* system_prompt, cJSON* messages,
791	    const char* tools_json, llm_response_t* resp)
792	{
793	    memset(resp, 0, sizeof(*resp));
794	
795	    /* Snapshot config under lock */
796	    char model[64];
797	    char api_key[128];
798	    char llm_host[128];
799	
800	    pthread_mutex_lock(&s_llm_lock);
801	    memcpy(model, s_model, sizeof(model));
802	    memcpy(api_key, s_api_key, sizeof(api_key));
803	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
804	    pthread_mutex_unlock(&s_llm_lock);
805	
806	    if (api_key[0] == '\0') {
807	        return ERROR;
808	    }
809	
810	    cJSON* body = cJSON_CreateObject();
811	
812	    cJSON_AddStringToObject(body, "model",
813	        model_name_for_api(model, llm_host));
814	
815	    if (is_openai_compat_host(llm_host)) {
816	        cJSON_AddNumberToObject(body, "max_completion_tokens",
817	            AGENT_LLM_MAX_TOKENS_OPENAI);
818	    } else {
819	        cJSON_AddNumberToObject(body, "max_tokens",
820	            AGENT_LLM_MAX_TOKENS);
821	    }
822	
823	    /* Clone messages and prepend system message */
824	    cJSON* msgs = cJSON_Duplicate(messages, 1);
825	    cJSON* sys_msg = cJSON_CreateObject();
826	
827	    cJSON_AddStringToObject(sys_msg, "role", "system");
828	    cJSON_AddStringToObject(sys_msg, "content", system_prompt);
829	    cJSON_InsertItemInArray(msgs, 0, sys_msg);
830	    cJSON_AddItemToObject(body, "messages", msgs);
831	
832	    /* Convert tools to OpenAI format */
833	    cJSON* tools_arr = build_openai_tools_array(tools_json);
834	
835	    if (tools_arr) {
836	        cJSON_AddItemToObject(body, "tools", tools_arr);
837	    }
838	
839	    char* post_data = cJSON_PrintUnformatted(body);
840	
841	    cJSON_Delete(body);
842	    if (!post_data) {
843	        return ERROR;
844	    }
845	
846	    if (!validate_request_json(post_data)) {
847	        free(post_data);
848	        return ERROR;
849	    }
850	
851	    syslog(LOG_INFO,
852	        "[%s] OpenAI API with tools (model: %s, %d bytes)\n",
853	        TAG, model, (int)strlen(post_data));
854	
855	    resp_buf_t rb = { 0 };
856	    int status = 0;
857	    int err = ERROR;
858	    int retry;
859	
860	    for (retry = 0; retry <= AGENT_LLM_MAX_RETRIES; retry++) {
861	        if (retry > 0) {
862	            unsigned int delay = AGENT_LLM_RETRY_BASE_SEC << (retry - 1);
863	            syslog(LOG_WARNING, "[%s] Rate limited (429), retry %d/%d after %us\n",
864	                TAG, retry, AGENT_LLM_MAX_RETRIES, delay);
865	            sleep(delay);
866	        }
867	
868	        rb.len = 0;
869	        status = 0;
870	        err = llm_http_call(post_data, &rb, &status);
871	
872	        if (err != OK) {
873	            resp_buf_free(&rb);
874	            free(post_data);
875	            return err;
876	        }
877	
878	        if (status != 429)
879	            break;
880	
881	        resp_buf_free(&rb);
882	        memset(&rb, 0, sizeof(rb));
883	    }
884	
885	    free(post_data);
886	
887	    if (status != 200) {
888	        syslog(LOG_ERR, "[%s] API error %d: %.500s\n", TAG, status,
889	            rb.data ? rb.data : "");
890	        resp_buf_free(&rb);
891	        return ERROR;
892	    }
893	
894	    cJSON* root = cJSON_Parse(rb.data);
895	
896	    resp_buf_free(&rb);
897	    if (!root) {
898	        syslog(LOG_ERR, "[%s] Failed to parse API JSON\n", TAG);
899	        return ERROR;
900	    }
901	
902	    /* Extract from OpenAI response */
903	    cJSON* choices = cJSON_GetObjectItem(root, "choices");
904	
905	    if (!choices || !cJSON_IsArray(choices) || !choices->child) {
906	        cJSON_Delete(root);
907	        return ERROR;
908	    }
909	
910	    cJSON* choice = choices->child;
911	    cJSON* finish = cJSON_GetObjectItem(choice, "finish_reason");
912	
913	    resp->tool_use = (finish && cJSON_IsString(finish)
914	        && strcmp(finish->valuestring, "tool_calls") == 0);
915	
916	    cJSON* message = cJSON_GetObjectItem(choice, "message");
917	
918	    if (message) {
919	        cJSON* text_content = cJSON_GetObjectItem(message, "content");
920	        if (text_content && cJSON_IsString(text_content) && text_content->valuestring) {
921	            size_t tlen = strlen(text_content->valuestring);
922	            resp->text = calloc(1, tlen + 1);
923	            if (resp->text) {
924	                memcpy(resp->text, text_content->valuestring, tlen);
925	                resp->text_len = tlen;
926	            }
927	        }
928	
929	        /* Kimi thinking mode: preserve reasoning_content so it can be echoed
930	         * back in the next turn (required by the API). */
931	        cJSON* rc = cJSON_GetObjectItem(message, "reasoning_content");
932	        if (rc && cJSON_IsString(rc) && rc->valuestring && rc->valuestring[0]) {
933	            resp->reasoning_content = strdup(rc->valuestring);
934	        }
935	
936	        /* Extract tool calls from OpenAI format */
937	        cJSON* tool_calls = cJSON_GetObjectItem(message, "tool_calls");
938	        if (tool_calls && cJSON_IsArray(tool_calls)) {
939	            cJSON* tc;
940	            cJSON_ArrayForEach(tc, tool_calls)
941	            {
942	                if (resp->call_count >= AGENT_MAX_TOOL_CALLS)
943	                    break;
944	
945	                llm_tool_call_t* call = &resp->calls[resp->call_count];
946	
947	                /* OpenAI tool_calls format:
948	                   { "id": "call_xyz", "type": "function",
949	                     "function": { "name": "foo", "arguments": "{...}" }
950	                   }
951	                */
952	                cJSON* id_item = cJSON_GetObjectItem(tc, "id");
953	                if (id_item && cJSON_IsString(id_item))
954	                    strncpy(call->id, id_item->valuestring, sizeof(call->id) - 1);
955	
956	                cJSON* func_obj = cJSON_GetObjectItem(tc, "function");
957	                if (func_obj) {
958	                    cJSON* name_item = cJSON_GetObjectItem(func_obj, "name");
959	                    cJSON* args_item = cJSON_GetObjectItem(func_obj, "arguments");
960	
961	                    if (name_item && cJSON_IsString(name_item))
962	                        strncpy(call->name, name_item->valuestring, sizeof(call->name) - 1);
963	
964	                    if (args_item && cJSON_IsString(args_item)) {
965	                        size_t alen = strlen(args_item->valuestring);
966	                        call->input = calloc(1, alen + 1);
967	                        if (call->input) {
968	                            memcpy(call->input, args_item->valuestring, alen);
969	                            call->input_len = alen;
970	                        }
971	                    } else if (args_item && cJSON_IsObject(args_item)) {
972	                        /* Some models return arguments as a JSON object
