231	void cmd_set_vision_llm(int argc, char** argv)
232	{
233	    if (argc < 2) {
234	        printf("Usage: set_vision_llm <preset> [api_key]\n"
235	               "       set_vision_llm <host> <model> [api_key]\n"
236	               "       set_vision_llm clear\n"
237	               "\n"
238	               "Set an independent vision model. If not configured,\n"
239	               "vision calls inherit the main LLM config.\n"
240	               "\n"
241	               "Presets:\n"
242	               "  mimo     - api.xiaomimimo.com  (mimo-v2-omni)\n"
243	               "  openai   - api.openai.com  (gpt-4o)\n"
244	               "  qwen     - dashscope.aliyuncs.com  (qwen-vl-max)\n"
245	               "  glm      - open.bigmodel.cn  (glm-4v-flash)\n"
246	               "\n"
247	               "Examples:\n"
248	               "  set_vision_llm mimo <api_key>\n"
249	               "  set_vision_llm clear\n");
250	        return;
251	    }
252	
253	    const char* arg1 = argv[1];
254	
255	    /* clear: remove vision-specific config, fall back to main LLM */
256	    if (strcmp(arg1, "clear") == 0) {
257	        llm_set_vision_model(NULL, NULL, NULL);
258	        printf("Vision LLM config cleared (using main LLM).\n");
259	        return;
