331	static void accumulate_pcm_locked(const unsigned char* chunk, size_t len)
332	{
333	    if (s_voice.pcm_buf && s_voice.pcm_len + len <= s_voice.pcm_cap) {
334	        memcpy(s_voice.pcm_buf + s_voice.pcm_len, chunk, len);
