371	/* ── Recording thread (PTT mode — streaming ASR) ─────────── */
372	
373	static void* recording_thread(void* arg)
374	{
375	    (void)arg;
376	    unsigned char chunk[AGENT_ASR_CHUNK_SIZE];
377	    int need_fallback = 0;
378	    // int dump_fd = -1;
379	    size_t total_bytes_read = 0;
380	    size_t total_bytes_sent = 0;
381	    int chunk_count = 0;
382	    int abnormal_exit = 0;
383	
384	    syslog(LOG_INFO, "[%s] recording thread started (streaming)\n", TAG);
385	
386	    /* Use pre-connected ASR stream if available (opened in
387	     * voice_channel_start to avoid TLS handshake delay during
388	     * recording).  Fall back to opening a new session if not. */
389	    pthread_mutex_lock(&s_voice.lock);
390	    voice_asr_stream_t* stream = s_voice.asr_stream;
391	    s_voice.asr_stream = NULL; /* thread now owns it */
392	    pthread_mutex_unlock(&s_voice.lock);
393	
394	    if (!stream) {
395	        /* No pre-connected stream — open now (may lose first 300-800ms) */
396	        stream = voice_asr_stream_open();
397	        syslog(LOG_WARNING,
398	            "[%s] streaming ASR unavailable, batch fallback\n", TAG);
399	        need_fallback = 1;
400	
401	        pthread_mutex_lock(&s_voice.lock);
402	        if (alloc_fallback_buffer_locked() != 0) {
403	            s_voice.state = VOICE_IDLE;
404	            pthread_mutex_unlock(&s_voice.lock);
405	            sem_post(&s_voice.rec_ready);
406	            return NULL;
407	        }
408	        pthread_mutex_unlock(&s_voice.lock);
409	    } else {
410	        syslog(LOG_INFO, "[%s] using pre-connected ASR stream\n", TAG);
411	    }
412	
413	    /* Signal voice_channel_start() that we are ready to consume
414	     * audio frames. Without this, sem_wait in start() deadlocks. */
415	    sem_post(&s_voice.rec_ready);
416	
417	    /* No flush needed: the new start sequence guarantees that
418	     * audio_capture_start() runs AFTER this thread is ready,
419	     * so there is no stale data in the queue. The old flush
420	     * was harmful — audio_capture_read() blocks, so it would
421	     * consume real audio frames instead of stale ones. */
422	
423	    while (1) {
424	        pthread_mutex_lock(&s_voice.lock);
425	        enum voice_state st = s_voice.state;
426	        pthread_mutex_unlock(&s_voice.lock);
427	
428	        if (st != VOICE_RECORDING) {
429	            break;
430	        }
431	
432	        int n = audio_capture_read(s_voice.cap,
433	            chunk, sizeof(chunk));
434	
435	        if (n == -EAGAIN || n == -EWOULDBLOCK) {
436	            /* Non-blocking capture socket has no data yet (common right
437	             * after start before the first frames arrive). Retry instead
438	             * of treating it as a fatal error. */
439	            usleep(10000);
440	            continue;
441	        }
442	
443	        if (n <= 0) {
444	            syslog(LOG_WARNING,
445	                "[%s] capture read returned %d, stopping\n", TAG, n);
446	            abnormal_exit = 1;
447	            break;
448	        }
449	
450	        total_bytes_read += (size_t)n;
451	        chunk_count++;
452	
453	        /* Dump raw PCM to file */
454	        // if (dump_fd >= 0) {
455	        //     write(dump_fd, chunk, (size_t)n);
456	        // }
457	
458	        /* Log audio level for first few chunks and periodically
459	         * to diagnose silence vs actual speech from QEMU mic. */
460	        if (chunk_count <= 3 || chunk_count % 50 == 0) {
461	            int16_t* samples = (int16_t*)chunk;
462	            int sample_count = n / 2;
463	            int32_t peak = 0;
464	
465	            for (int i = 0; i < sample_count; i++) {
466	                int32_t v = samples[i] < 0 ? -samples[i] : samples[i];
467	                if (v > peak) {
468	                    peak = v;
469	                }
470	            }
471	            syslog(LOG_INFO,
472	                "[%s] chunk#%d: %d bytes, peak=%ld\n",
473	                TAG, chunk_count, n, (long)peak);
474	        }
475	
476	#ifdef CONFIG_AI_AGENT_AUDIO_PREPROCESS
477	        preproc_chunk(pp, chunk, n);
478	#endif
479	
480	        process_audio_chunk(&stream, chunk, (size_t)n,
481	            &need_fallback, &total_bytes_sent);
482	    }
483	
484	#ifdef CONFIG_AI_AGENT_AUDIO_PREPROCESS
485	    preproc_destroy(pp);
486	#endif
487	
488	    /* Store stream handle for voice_channel_stop to finish */
489	    // if (dump_fd >= 0) {
490	    //     close(dump_fd);
491	    //     syslog(LOG_INFO, "[%s] PCM dump saved to /data/cap_dump.pcm\n", TAG);
492	    // }
493	
494	    pthread_mutex_lock(&s_voice.lock);
495	    s_voice.asr_stream = stream;
496	
497	    if (abnormal_exit && s_voice.state == VOICE_RECORDING) {
498	        syslog(LOG_WARNING, "[%s] abnormal exit, cleaning up\n", TAG);
499	        recording_cleanup_locked(stream);
500	    }
501	    pthread_mutex_unlock(&s_voice.lock);
502	
503	    syslog(LOG_INFO,
504	        "[%s] recording thread exit: %d chunks, %zu read, %zu sent%s\n",
505	        TAG, chunk_count, total_bytes_read, total_bytes_sent,
506	        abnormal_exit ? " (abnormal)" : "");
507	    return NULL;
508	}
509	
510	/* ── ASR worker thread ──────────────────────────────────── */
826	    /* Batch fallback: pcm_buf must exist if we reach here */
827	    if (!s_voice.pcm_buf || pcm_len == 0) {
828	        free(s_voice.pcm_buf);
829	        s_voice.pcm_buf = NULL;
830	        syslog(LOG_ERR, "[%s] no PCM data for batch ASR\n", TAG);
831	        return -ENODATA;
832	    }
833	
834	    /* Batch fallback: pack pcm_len + audio for ASR thread */
835	    size_t total = sizeof(size_t) + pcm_len;
836	    unsigned char* pkg = malloc(total);
837	
838	    if (!pkg) {
839	        free(s_voice.pcm_buf);
840	        s_voice.pcm_buf = NULL;
841	        return -ENOMEM;
842	    }
843	
844	    memcpy(pkg, &pcm_len, sizeof(size_t));
845	    memcpy(pkg + sizeof(size_t), s_voice.pcm_buf, pcm_len);
846	    free(s_voice.pcm_buf);
847	    s_voice.pcm_buf = NULL;
848	
849	    /* Spawn ASR worker thread */
850	    int ret = agent_task_create(asr_and_dispatch, "asr_worker",
851	        ASR_THREAD_STACK, pkg, AGENT_VOICE_PRIO);
852	
853	    if (ret != OK) {
854	        free(pkg);
855	        return -EIO;
856	    }
857	
858	    return 0;
859	}
