861	int voice_channel_stop_with_text(char* text_out, size_t text_cap)
862	{
863	    if (!text_out || text_cap == 0) {
864	        return -EINVAL;
865	    }
866	
867	    text_out[0] = '\0';
868	
869	    pthread_mutex_lock(&s_voice.lock);
870	    if (s_voice.state != VOICE_RECORDING) {
871	        pthread_mutex_unlock(&s_voice.lock);
872	        return -EINVAL;
873	    }
874	    s_voice.state = VOICE_STOPPING;
875	    pthread_mutex_unlock(&s_voice.lock);
876	
877	    audio_capture_abort(s_voice.cap);
878	
879	    /* Wait for recording thread to finish */
880	    pthread_join(s_voice.rec_thread, NULL);
881	
882	    /* Close capture device */
883	    audio_capture_close(s_voice.cap);
884	
885	    pthread_mutex_lock(&s_voice.lock);
886	    s_voice.cap = NULL;
887	    size_t pcm_len = s_voice.pcm_len;
888	    voice_asr_stream_t* stream = s_voice.asr_stream;
889	    s_voice.asr_stream = NULL;
890	    s_voice.state = VOICE_IDLE;
891	    pthread_mutex_unlock(&s_voice.lock);
892	
893	    syslog(LOG_INFO, "[%s] recorded %zu bytes (with_text, stream=%p)\n",
894	        TAG, pcm_len, (void*)stream);
895	
896	    /* Streaming ASR path: finish and copy text to caller.
897	     * In streaming mode audio goes directly to server, so
898	     * pcm_len may be 0 — that's OK, don't abort. */
899	    if (stream) {
900	        char text[512];
901	        int ret = voice_asr_stream_finish(stream, text,
902	            sizeof(text));
903	
904	        free(s_voice.pcm_buf);
905	        s_voice.pcm_buf = NULL;
906	
907	        if (ret == 0 && text[0] != '\0') {
908	            syslog(LOG_INFO, "[%s] stream ASR (with_text): %s\n",
909	                TAG, text);
910	            strncpy(text_out, text, text_cap - 1);
911	            text_out[text_cap - 1] = '\0';
912	        }
913	        return 0;
914	    }
915	
916	    /* Batch fallback: synchronous ASR inline (no thread) */
917	    if (!s_voice.pcm_buf || pcm_len == 0) {
918	        free(s_voice.pcm_buf);
919	        s_voice.pcm_buf = NULL;
920	        syslog(LOG_ERR, "[%s] no PCM data for batch ASR\n", TAG);
921	        return -ENODATA;
922	    }
923	
924	    syslog(LOG_INFO, "[%s] batch ASR (with_text): %zu bytes\n",
925	        TAG, pcm_len);
926	
927	    char text[512];
928	    int ret = voice_asr_recognize(s_voice.pcm_buf, pcm_len,
929	        text, sizeof(text));
930	
931	    free(s_voice.pcm_buf);
932	    s_voice.pcm_buf = NULL;
933	
934	    if (ret == 0 && text[0] != '\0') {
935	        syslog(LOG_INFO, "[%s] batch ASR result: %s\n", TAG, text);
936	        strncpy(text_out, text, text_cap - 1);
937	        text_out[text_cap - 1] = '\0';
938	    } else if (ret != 0) {
939	        syslog(LOG_WARNING, "[%s] batch ASR failed: %d\n",
940	            TAG, ret);
941	    }
