331	/**
332	 * Reads messages from the outbound queue and dispatches them to the
333	 * appropriate channel (FeiShu, WebSocket, CLI, etc.).
334	 */
335	static void* outbound_dispatch_task(void* arg)
336	{
337	    (void)arg;
338	    syslog(LOG_INFO, "[%s] Outbound dispatch started\n", TAG);
339	
340	    while (!g_shutdown_requested) {
341	        agent_msg_t msg;
342	        if (message_bus_pop_outbound(&msg, 1000) != OK)
343	            continue;
344	        msg.channel[sizeof(msg.channel) - 1] = '\0';
345	        msg.chat_id[sizeof(msg.chat_id) - 1] = '\0';
346	
347	        if (!msg.content) {
348	            syslog(LOG_WARNING, "[%s] Skip outbound message with NULL content\n", TAG);
349	            continue;
350	        }
351	
352	        syslog(LOG_INFO, "[%s] Dispatching response → %s:%s\n", TAG, msg.channel, msg.chat_id);
353	
354	        /* Let registered taps intercept before normal dispatch */
355	        if (mbus_tap_try_deliver(&msg)) {
356	            free(msg.content);
357	            continue;
358	        }
359	
360	        if (strcmp(msg.channel, AGENT_CHAN_FEISHU) == 0) {
361	            bool delivered = false;
362	#ifdef CONFIG_AI_AGENT_FEISHU
363	            const char* app_id = feishu_get_app_id();
364	            if (app_id && app_id[0] != '\0') {
365	                feishu_send_message(msg.chat_id, msg.content);
366	                delivered = true;
367	            }
368	#endif
369	#ifdef CONFIG_AI_AGENT_NODE
370	            if (!delivered) {
371	                delivered = node_client_send_chat_message(
372	                    msg.channel, msg.chat_id, msg.content) == OK;
373	            }
374	#endif
375	            if (!delivered) {
376	                syslog(LOG_WARNING,
377	                    "[%s] Feishu message dropped: no local config "
378	                    "and no gateway\n",
379	                    TAG);
380	            }
381	        } else if (strcmp(msg.channel, AGENT_CHAN_WEBSOCKET) == 0) {
382	            ws_server_send(msg.chat_id, msg.content);
383	#ifdef CONFIG_AI_AGENT_MQTT
384	        } else if (strcmp(msg.channel, AGENT_CHAN_MQTT) == 0) {
385	            mqtt_channel_send(msg.chat_id, msg.content);
386	#endif
387	        } else if (strcmp(msg.channel, AGENT_CHAN_VOICE) == 0) {
388	            /* Check voice cooldown — skip voice dispatch if a recent
389	             * speak call failed, to prevent error-message cascade. */
390	            if (s_voice_cooldown && time(NULL) < s_voice_cooldown_until) {
391	                syslog(LOG_WARNING,
392	                    "[%s] voice cooldown active, dropping message\n", TAG);
393	            } else {
394	                s_voice_cooldown = false;
395	                int vret = voice_channel_speak(msg.content);
396	                if (vret != 0) {
397	                    syslog(LOG_ERR, "[%s] voice_channel_speak failed: %d\n", TAG, vret);
398	                    s_voice_cooldown = true;
399	                    s_voice_cooldown_until = time(NULL) + 5;
400	                }
401	            }
402	#ifdef CONFIG_AI_AGENT_LVGL_UI
403	        } else if (strcmp(msg.channel, AGENT_CHAN_LVGL_UI) == 0) {
404	            int uret = lvgl_ui_channel_send(msg.content);
405	            if (uret != 0) {
406	                syslog(LOG_ERR, "[%s] lvgl_ui_channel_send failed: %d\n", TAG, uret);
407	            }
408	#endif
409	#ifdef CONFIG_AI_AGENT_WEIXIN
410	        } else if (strcmp(msg.channel, AGENT_CHAN_WEIXIN) == 0) {
411	            /* chat_id format: "from_user_id|context_token" */
412	            char uid[64] = "";
413	            const char* ctx = "";
414	            char* sep = strchr(msg.chat_id, '|');
415	            if (sep) {
416	                size_t ulen = (size_t)(sep - msg.chat_id);
417	                if (ulen >= sizeof(uid))
418	                    ulen = sizeof(uid) - 1;
419	                memcpy(uid, msg.chat_id, ulen);
420	                uid[ulen] = '\0';
421	                ctx = sep + 1;
422	            } else {
423	                strncpy(uid, msg.chat_id, sizeof(uid) - 1);
424	            }
425	            weixin_channel_send(uid, ctx, msg.content);
426	#endif
427	        } else if (strcmp(msg.channel, AGENT_CHAN_SYSTEM) == 0) {
428	            syslog(LOG_INFO, "[%s] System message [%s]: %.128s\n", TAG, msg.chat_id, msg.content);
