 62	#define VOLC_MSG_FULL_REQ 0x10 /* full_client_request */
 63	#define VOLC_MSG_AUDIO 0x20 /* audio_only, not last */
 64	#define VOLC_MSG_AUDIO_LAST 0x22 /* audio_only, last chunk */
 65	#define VOLC_MSG_FULL_RESP 0x90 /* full_server_response */
 66	#define VOLC_MSG_ERROR 0xF0 /* server error */
 67	#define VOLC_SER_JSON 0x10 /* JSON, no compression */
 68	#define VOLC_SER_RAW 0x00 /* raw audio, no compression */
