 81	/* TLS context for ASR connection (not pooled — single use) */
 82	typedef struct {
 83	    mbedtls_ssl_context ssl;
 84	    mbedtls_ssl_config cfg;
 85	    mbedtls_net_context net;
 86	    mbedtls_ctr_drbg_context ctr_drbg;
 87	} asr_tls_ctx_t;
 88	
 89	/* ── Entropy source ──────────────────────────────────────────── */
 90	
 91	static int asr_entropy_func(void* data, unsigned char* output, size_t len)
 92	{
 93	    (void)data;
 94	    if (agent_secure_random(output, len) == 0) {
 95	        return 0;
 96	    }
 97	    syslog(LOG_ERR, "[volc_asr] CRITICAL: No secure entropy source available\n");
 98	    return -1;  /* Generic error - TLS handshake will fail safely */
 99	}
100	
101	/* ── TLS connect / free ──────────────────────────────────────── */
102	
103	static int asr_tls_connect(asr_tls_ctx_t* ctx,
104	    const char* host, const char* port)
105	{
106	    int ret;
107	
108	    mbedtls_ssl_init(&ctx->ssl);
109	    mbedtls_ssl_config_init(&ctx->cfg);
110	    mbedtls_net_init(&ctx->net);
111	    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);
112	
113	    const char* pers = "volc_asr";
114	
115	    ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, asr_entropy_func,
116	        NULL, (const unsigned char*)pers,
117	        strlen(pers));
118	    if (ret != 0) {
119	        syslog(LOG_ERR, "[%s] ctr_drbg_seed: -0x%04x\n", TAG, -ret);
120	        return -EIO;
121	    }
122	
123	    /* If proxy is enabled, open a CONNECT tunnel first */
124	    if (http_proxy_is_enabled()) {
125	        int port_num = atoi(port);
126	        int tunnel_fd = proxy_open_tunnel(host, port_num, 30000);
127	
128	        if (tunnel_fd < 0) {
129	            syslog(LOG_ERR, "[%s] proxy tunnel failed\n", TAG);
130	            return -ECONNREFUSED;
131	        }
132	
133	        ctx->net.fd = tunnel_fd;
134	        syslog(LOG_INFO, "[%s] Using proxy tunnel fd=%d for %s:%s\n",
135	            TAG, tunnel_fd, host, port);
136	    } else {
137	        ret = mbedtls_net_connect(&ctx->net, host, port,
138	            MBEDTLS_NET_PROTO_TCP);
139	        if (ret != 0) {
140	            syslog(LOG_ERR, "[%s] net_connect %s:%s: -0x%04x\n",
141	                TAG, host, port, -ret);
142	            return -ECONNREFUSED;
143	        }
144	    }
145	
146	    mbedtls_net_set_block(&ctx->net);
147	    if (ctx->net.fd >= 0) {
148	        struct timeval tv = { .tv_sec = 30, .tv_usec = 0 };
149	
150	        setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO,
151	            &tv, sizeof(tv));
152	    }
153	
154	    ret = mbedtls_ssl_config_defaults(&ctx->cfg,
155	        MBEDTLS_SSL_IS_CLIENT,
156	        MBEDTLS_SSL_TRANSPORT_STREAM,
157	        MBEDTLS_SSL_PRESET_DEFAULT);
158	    if (ret != 0) {
159	        return -EIO;
160	    }
