 64	
 65	    if (!params) {
 66	        cJSON_Delete(root);
 67	        return NULL;
 68	    }
 69	
 70	    cJSON_AddStringToObject(params, "text", text);
 71	    cJSON_AddStringToObject(params, "speaker", speaker);
 72	
 73	    cJSON* audio = cJSON_CreateObject();
 74	
