 27	/**
 28	 * LLM Router - Intelligent model routing inspired by ClawRouter
 29	 *
 30	 * Features:
 31	 * - Multi-backend support (up to 4 backends)
 32	 * - Complexity-based routing (simple/medium/complex)
 33	 * - Automatic failover on backend failure
 34	 * - Cost optimization (eco/auto/premium profiles)
 35	 */
 36	
 37	/* Maximum number of LLM backends */
 38	#define LLM_ROUTER_MAX_BACKENDS 4
 39	
 40	/* Routing profiles (inspired by ClawRouter) */
 41	typedef enum {
 42	    LLM_ROUTE_AUTO = 0, /* Balanced: quality vs cost */
 43	    LLM_ROUTE_ECO, /* Cheapest model */
 44	    LLM_ROUTE_PREMIUM, /* Best quality */
 45	} llm_route_profile_t;
 46	
 47	/* Task complexity levels */
 48	typedef enum {
 49	    LLM_COMPLEXITY_SIMPLE = 0, /* Short queries, simple tasks */
 50	    LLM_COMPLEXITY_MEDIUM, /* Normal conversations */
 51	    LLM_COMPLEXITY_COMPLEX, /* Reasoning, coding, analysis */
 52	} llm_complexity_t;
 53	
 54	/* Backend configuration */
 55	typedef struct {
 56	    char host[128];
 57	    char path[128];
 58	    char port[8];
 59	    char api_key[128];
 60	    char model[64];
 61	    int priority; /* Lower = higher priority */
 62	    int cost_tier; /* 0=free, 1=cheap, 2=mid, 3=premium */
 63	    bool enabled;
 64	    int fail_count; /* Consecutive failures */
 65	
 66	    /* P0 improvements: metrics + backoff (from scout report 2026-03-21) */
 67	    uint32_t last_fail_ts; /* Epoch seconds of last failure */
 68	    uint32_t backoff_until; /* Don't use until this epoch */
 69	    uint32_t total_calls; /* Lifetime call count */
 70	    uint32_t total_failures; /* Lifetime failure count */
 71	    uint32_t avg_latency_ms; /* Exponential moving average */
 72	    uint32_t total_prompt_tokens; /* Cumulative prompt tokens */
 73	    uint32_t total_completion_tokens; /* Cumulative completion tokens */
 74	} llm_backend_t;
