 76	/* ── Helper: check if string contains keyword ─────────────── */
 77	
 78	static bool contains_keyword(const char* text, const char** keywords)
 79	{
 80	    if (!text || !keywords) {
 81	        return false;
 82	    }
 83	    for (int i = 0; keywords[i] != NULL; i++) {
 84	        if (strcasestr(text, keywords[i]) != NULL) {
 85	            return true;
 86	        }
 87	    }
 88	    return false;
 89	}
