 91	/* ── Init ─────────────────────────────────────────────────── */
 92	
 93	int llm_router_init(void)
 94	{
 95	    pthread_mutex_lock(&s_router_lock);
 96	
 97	    /* Load profile from config */
 98	    char tmp[32] = { 0 };
 99	    if (claw_config_get(CFG_KEY_ROUTER_PROFILE, tmp, sizeof(tmp)) == 0) {
100	        if (strcmp(tmp, "eco") == 0) {
101	            s_profile = LLM_ROUTE_ECO;
102	        } else if (strcmp(tmp, "premium") == 0) {
103	            s_profile = LLM_ROUTE_PREMIUM;
104	        } else {
105	            s_profile = LLM_ROUTE_AUTO;
106	        }
107	    }
108	
109	    /* Load backends from config */
110	    s_backend_count = 0;
111	    for (int i = 0; i < LLM_ROUTER_MAX_BACKENDS; i++) {
112	        char key[64];
113	        char json[1024] = { 0 };
114	
115	        snprintf(key, sizeof(key), "%s%d", CFG_KEY_BACKEND_PREFIX, i);
116	        if (claw_config_get(key, json, sizeof(json)) != 0 || json[0] == '\0') {
117	            continue;
118	        }
119	
120	        cJSON* obj = cJSON_Parse(json);
121	        if (!obj) {
122	            continue;
123	        }
124	
125	        llm_backend_t* b = &s_backends[i];
126	        memset(b, 0, sizeof(*b));
127	
128	        cJSON* item;
129	        if ((item = cJSON_GetObjectItem(obj, "host")) && cJSON_IsString(item)) {
130	            strncpy(b->host, item->valuestring, sizeof(b->host) - 1);
131	        }
132	        if ((item = cJSON_GetObjectItem(obj, "path")) && cJSON_IsString(item)) {
133	            strncpy(b->path, item->valuestring, sizeof(b->path) - 1);
134	        }
135	        if ((item = cJSON_GetObjectItem(obj, "port")) && cJSON_IsString(item)) {
136	            strncpy(b->port, item->valuestring, sizeof(b->port) - 1);
137	        }
138	        if ((item = cJSON_GetObjectItem(obj, "api_key")) && cJSON_IsString(item)) {
139	            strncpy(b->api_key, item->valuestring, sizeof(b->api_key) - 1);
140	        }
141	        if ((item = cJSON_GetObjectItem(obj, "model")) && cJSON_IsString(item)) {
142	            strncpy(b->model, item->valuestring, sizeof(b->model) - 1);
143	        }
144	        if ((item = cJSON_GetObjectItem(obj, "priority")) && cJSON_IsNumber(item)) {
145	            b->priority = item->valueint;
146	        }
147	        if ((item = cJSON_GetObjectItem(obj, "cost_tier")) && cJSON_IsNumber(item)) {
148	            b->cost_tier = item->valueint;
149	        }
150	
151	        b->enabled = true;
152	        b->fail_count = 0;
153	        s_backend_count++;
154	
155	        cJSON_Delete(obj);
156	        syslog(LOG_INFO, "[%s] Loaded backend %d: %s (model: %s, tier: %d)\n",
157	            TAG, i, b->host, b->model, b->cost_tier);
158	    }
159	
160	    pthread_mutex_unlock(&s_router_lock);
161	
162	    syslog(LOG_INFO, "[%s] Router initialized: %d backends, profile=%d\n",
163	        TAG, s_backend_count, s_profile);
164	    return 0;
165	}
