215	int llm_router_get_backend(int index, llm_backend_t* backend)
216	{
217	    if (index < 0 || index >= LLM_ROUTER_MAX_BACKENDS || !backend) {
218	        return -1;
219	    }
220	
221	    pthread_mutex_lock(&s_router_lock);
222	    if (!s_backends[index].enabled || s_backends[index].host[0] == '\0') {
223	        pthread_mutex_unlock(&s_router_lock);
224	        return -1;
225	    }
226	    memcpy(backend, &s_backends[index], sizeof(llm_backend_t));
227	    pthread_mutex_unlock(&s_router_lock);
228	
229	    return 0;
230	}
