504	/* ── Apply backend to llm_proxy ───────────────────────────── */
505	
506	int llm_router_apply(int index)
507	{
508	    if (index < 0 || index >= LLM_ROUTER_MAX_BACKENDS) {
509	        return -1;
510	    }
511	
512	    llm_backend_t b;
513	    pthread_mutex_lock(&s_router_lock);
514	    memcpy(&b, &s_backends[index], sizeof(b));
515	    pthread_mutex_unlock(&s_router_lock);
516	
517	    if (b.host[0] == '\0') {
518	        return -1;
519	    }
520	
521	    /* Atomic update — single lock acquisition in llm_proxy */
522	    llm_set_all(b.host, b.path, b.port, b.api_key, b.model);
523	
