  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_RESET);
  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), I2S_RX_RESET, 0);
  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_FIFO_RESET);
